using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using Ucall;

var builder=WebApplication.CreateBuilder(args);
builder.Logging.ClearProviders();builder.Logging.AddConsole();
var root=Path.GetFullPath(builder.Configuration["Storage:Root"]??"data");Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,"keys"));Directory.CreateDirectory(Path.Combine(root,"evidence"));
builder.Services.AddDataProtection().PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(root,"keys"))).SetApplicationName("UcallTransformation");
builder.Services.AddDbContext<AppDb>(o=>{if(builder.Configuration["Database:Provider"]=="Sqlite")o.UseSqlite(builder.Configuration.GetConnectionString("Database")??$"Data Source={Path.Combine(root,"development.db")}");else o.UseNpgsql(builder.Configuration.GetConnectionString("Database")??throw new InvalidOperationException("Configura ConnectionStrings__Database para uma base PostgreSQL dedicada."));});
builder.Services.AddDbContext<RequestsDb>(o=>{if(builder.Configuration["Database:Provider"]=="Sqlite")o.UseSqlite(builder.Configuration.GetConnectionString("Database")??$"Data Source={Path.Combine(root,"development.db")}");else o.UseNpgsql(builder.Configuration.GetConnectionString("Database"));});
builder.Services.AddIdentity<User,IdentityRole>(o=>{o.Password.RequiredLength=12;o.User.RequireUniqueEmail=true;o.Lockout.MaxFailedAccessAttempts=5;o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15);}).AddEntityFrameworkStores<AppDb>().AddDefaultTokenProviders();
builder.Services.ConfigureApplicationCookie(o=>{o.Cookie.Name="ucall.session";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;o.Cookie.SecurePolicy=builder.Environment.IsDevelopment()?CookieSecurePolicy.SameAsRequest:CookieSecurePolicy.Always;o.ExpireTimeSpan=TimeSpan.FromHours(8);o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=401;return Task.CompletedTask;};o.Events.OnRedirectToAccessDenied=c=>{c.Response.StatusCode=403;return Task.CompletedTask;};});
builder.Services.Configure<SecurityStampValidatorOptions>(o=>o.ValidationInterval=TimeSpan.Zero);
builder.Services.AddAuthorization(o=>{o.AddPolicy("Leader",p=>p.RequireRole("leader").RequireClaim("person_id","paulo"));o.AddPolicy("Leadership",p=>p.RequireRole("leader","ce"));});
builder.Services.AddAntiforgery(o=>{o.HeaderName="X-CSRF-TOKEN";o.Cookie.SameSite=SameSiteMode.Strict;});
builder.Services.AddRateLimiter(o=>{o.AddPolicy("request-submit",context=>RateLimitPartition.GetFixedWindowLimiter(context.Connection.RemoteIpAddress?.ToString()??"local",_=>new(){PermitLimit=30,Window=TimeSpan.FromMinutes(10),QueueLimit=0}));o.AddPolicy("login",context=>RateLimitPartition.GetFixedWindowLimiter(context.Connection.RemoteIpAddress?.ToString()??"local",_=>new(){PermitLimit=10,Window=TimeSpan.FromMinutes(1),QueueLimit=0}));o.AddPolicy("advisor",context=>RateLimitPartition.GetFixedWindowLimiter(context.User.FindFirstValue(ClaimTypes.NameIdentifier)??"unknown",_=>new(){PermitLimit=10,Window=TimeSpan.FromMinutes(1),QueueLimit=0}));o.RejectionStatusCode=429;});
builder.Services.AddScoped<SmtpMailer>();builder.Services.AddScoped<ConfigurationStore>();builder.Services.AddScoped<Advisor>();builder.Services.AddScoped<UserManagerAdapter>();builder.Services.AddScoped<AlertEngine>();builder.Services.AddHttpClient("openai",c=>c.Timeout=TimeSpan.FromSeconds(90));if(builder.Configuration["Alerts:Disabled"]!="true")builder.Services.AddHostedService<AlertWorker>();
builder.Services.ConfigureHttpJsonOptions(o=>o.SerializerOptions.ReferenceHandler=System.Text.Json.Serialization.ReferenceHandler.IgnoreCycles);
var app=builder.Build();
if(args.Contains("--export-schema")){using var schemaScope=app.Services.CreateScope();Console.WriteLine(schemaScope.ServiceProvider.GetRequiredService<AppDb>().Database.GenerateCreateScript());return;}
using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDb>();if(builder.Configuration.GetValue<bool>("Database:Initialize"))await db.Database.EnsureCreatedAsync();await scope.ServiceProvider.GetRequiredService<RequestsDb>().Upgrade();await Seed.Run(db,scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>());}
if(args.Contains("--process-alerts")){using var alertScope=app.Services.CreateScope();await alertScope.ServiceProvider.GetRequiredService<AlertEngine>().Run(CancellationToken.None);Console.WriteLine("Alertas processados.");return;}
app.UseAuthentication();app.UseAuthorization();app.UseRateLimiter();
app.Use(async(ctx,next)=>{ctx.Response.Headers["X-Content-Type-Options"]="nosniff";ctx.Response.Headers["Referrer-Policy"]="same-origin";ctx.Response.Headers["X-Frame-Options"]="DENY";if(ctx.Request.Path.StartsWithSegments("/api")){ctx.Response.Headers.CacheControl="no-store";if(ctx.Request.Method is "POST" or "PUT" or "DELETE" or "PATCH"){try{await ctx.RequestServices.GetRequiredService<IAntiforgery>().ValidateRequestAsync(ctx);}catch(AntiforgeryValidationException){ctx.Response.StatusCode=400;await ctx.Response.WriteAsJsonAsync(new{error="Sessão expirada. Recarrega a página."});return;}}}try{await next();}catch(DbUpdateConcurrencyException){ctx.Response.StatusCode=409;await ctx.Response.WriteAsJsonAsync(new{error="Esta acção foi alterada por outra pessoa. Recarrega antes de gravar."});}catch(InvalidOperationException){if(!ctx.Response.HasStarted){ctx.Response.StatusCode=400;await ctx.Response.WriteAsJsonAsync(new{error="Não foi possível concluir o pedido. Revê os dados."});}}catch(Exception){if(!ctx.Response.HasStarted){ctx.Response.StatusCode=500;await ctx.Response.WriteAsJsonAsync(new{error="Ocorreu um erro no servidor. Tenta novamente."});}}});
app.UseDefaultFiles();app.UseStaticFiles();
DevelopmentRequests.Map(app);
app.MapGet("/health",()=>Results.Ok(new{status="ok"}));
app.MapGet("/api/csrf",(HttpContext c,IAntiforgery a)=>Results.Ok(new{token=a.GetAndStoreTokens(c).RequestToken}));
app.MapGet("/api/setup",async(AppDb db)=>Results.Ok(new{required=!await db.Users.AnyAsync()}));
app.MapPost("/api/setup",async(SetupInput input,AppDb db,UserManager<User> users,SignInManager<User> signIn)=>{if(await db.Users.AnyAsync())return Results.Conflict(new{error="A configuração inicial já foi concluída."});var expected=builder.Configuration["Bootstrap:Token"];if(string.IsNullOrEmpty(expected)||!CryptographicOperations.FixedTimeEquals(SHA256.HashData(Encoding.UTF8.GetBytes(expected)),SHA256.HashData(Encoding.UTF8.GetBytes(input.Token))))return Results.Unauthorized();var user=new User{UserName=input.Email,Email=input.Email,DisplayName="Paulo Tavares",PersonId="paulo"};var result=await users.CreateAsync(user,input.Password);if(!result.Succeeded)return Results.BadRequest(new{error=string.Join(" ",result.Errors.Select(x=>x.Description))});await users.AddToRoleAsync(user,"leader");await users.AddClaimAsync(user,new Claim("person_id","paulo"));await signIn.SignInAsync(user,false);return Results.Ok(new{ok=true});}).RequireRateLimiting("login");
app.MapPost("/api/login",async(LoginInput input,SignInManager<User> signIn)=>{var result=await signIn.PasswordSignInAsync(input.Email,input.Password,false,true);return result.Succeeded?Results.Ok(new{ok=true}):Results.Json(new{error="E-mail ou password incorrectos, ou conta temporariamente bloqueada."},statusCode:401);}).RequireRateLimiting("login");
app.MapPost("/api/logout",async(SignInManager<User> s)=>{await s.SignOutAsync();return Results.Ok();}).RequireAuthorization();
var api=app.MapGroup("/api").RequireAuthorization();
api.MapGet("/me",async(ClaimsPrincipal principal,UserManager<User> users)=>{var u=await users.GetUserAsync(principal);return Results.Ok(new{u!.Id,u.Email,u.DisplayName,u.PersonId,roles=await users.GetRolesAsync(u)});});
api.MapGet("/people",async(AppDb db)=>Results.Ok(await db.People.OrderBy(x=>x.Name).ToListAsync()));
api.MapGet("/dashboard",async(AppDb db)=>Results.Ok(await Logic.Dashboard(db)));
api.MapGet("/actions",async(AppDb db)=>Results.Ok(await db.Actions.Include(x=>x.Evidence).Include(x=>x.History).Include(x=>x.Subtasks).OrderBy(x=>x.MandateNumber==null).ThenBy(x=>x.MandateNumber).ThenBy(x=>x.DueDate).ToListAsync()));
api.MapPost("/actions",async(ActionInput input,ClaimsPrincipal u,AppDb db)=>{if(!Logic.Leader(u))return Results.Forbid();var error=await ValidateAction(input,db);if(error!=null)return Results.BadRequest(new{error});var a=new WorkAction{OriginalDueDate=input.DueDate};ApplyAction(a,input);if(a.Status=="Concluída")return Results.BadRequest(new{error="Cria a acção, anexa evidência e só depois conclui."});db.Actions.Add(a);db.Changes.Add(new(){ActionId=a.Id,Actor=Logic.Person(u),Description="Acção adicional criada"});await db.SaveChangesAsync();return Results.Ok(a);});
api.MapPut("/actions/{id:guid}",async(Guid id,ActionInput input,ClaimsPrincipal u,AppDb db)=>{var a=await db.Actions.Include(x=>x.Evidence).FirstOrDefaultAsync(x=>x.Id==id);if(a==null)return Results.NotFound();if(!Logic.Edit(u,a))return Results.Forbid();if(input.Version!=a.Version)return Results.Conflict(new{error="Versão desactualizada. Recarrega a acção."});var error=await ValidateAction(input,db,id);if(error!=null)return Results.BadRequest(new{error});if(!Logic.Leader(u)&&(input.Title!=a.Title||input.OwnerId!=a.OwnerId||input.Participants!=a.Participants||input.DueDate!=a.DueDate||input.Phase!=a.Phase||input.Priority!=a.Priority||input.DependsOnId!=a.DependsOnId||input.MeetingId!=a.MeetingId||input.KpiId!=a.KpiId||input.Deliverable!=a.Deliverable))return Results.Forbid();if(input.Status=="Concluída"&&!a.Evidence.Any())return Results.BadRequest(new{error="Anexa evidência antes de concluir a acção."});if(a.DueDate!=input.DueDate){if(string.IsNullOrWhiteSpace(input.DeadlineReason))return Results.BadRequest(new{error="Indica o motivo da alteração de prazo."});db.Changes.Add(new(){ActionId=id,Actor=Logic.Person(u),Description=$"Prazo {a.DueDate:yyyy-MM-dd} → {input.DueDate:yyyy-MM-dd}. Motivo: {input.DeadlineReason}"});}db.Changes.Add(new(){ActionId=id,Actor=Logic.Person(u),Description=$"Actualização: {a.Status} ({a.Progress}%) → {input.Status} ({input.Progress}%)"});ApplyAction(a,input);a.UpdatedAt=Logic.Now;a.Version++;if(a.Status=="Concluída"){a.Progress=100;a.CompletedAt??=Logic.Now;}else a.CompletedAt=null;await db.SaveChangesAsync();return Results.Ok(a);});
api.MapPost("/actions/{id:guid}/comments",async(Guid id,TextInput input,ClaimsPrincipal u,AppDb db)=>{if(string.IsNullOrWhiteSpace(input.Text)||input.Text.Length>4000)return Results.BadRequest();if(!await db.Actions.AnyAsync(x=>x.Id==id))return Results.NotFound();db.Comments.Add(new(){ActionId=id,Author=Logic.Person(u),Text=input.Text.Trim()});await db.SaveChangesAsync();return Results.Ok();});
api.MapGet("/actions/{id:guid}/comments",async(Guid id,AppDb db)=>Results.Ok(await db.Comments.Where(x=>x.ActionId==id).OrderBy(x=>x.At).ToListAsync()));
api.MapPost("/actions/{id:guid}/subtasks",async(Guid id,SubtaskInput input,ClaimsPrincipal u,AppDb db)=>{var a=await db.Actions.FindAsync(id);if(a==null)return Results.NotFound();if(!Logic.Edit(u,a))return Results.Forbid();if(string.IsNullOrWhiteSpace(input.Title))return Results.BadRequest();db.Subtasks.Add(new(){ActionId=id,Title=input.Title.Trim(),Done=input.Done});a.UpdatedAt=Logic.Now;a.Version++;await db.SaveChangesAsync();return Results.Ok();});
api.MapPut("/subtasks/{id:guid}",async(Guid id,SubtaskInput input,ClaimsPrincipal u,AppDb db)=>{var s=await db.Subtasks.FindAsync(id);if(s==null)return Results.NotFound();var a=await db.Actions.FindAsync(s.ActionId);if(a==null||!Logic.Edit(u,a))return Results.Forbid();s.Done=input.Done;s.Title=input.Title.Trim();a.Version++;a.UpdatedAt=Logic.Now;await db.SaveChangesAsync();return Results.Ok();});
api.MapPost("/evidence/{type}/{id:guid}",async(string type,Guid id,HttpRequest request,ClaimsPrincipal u,AppDb db)=>{if(!request.HasFormContentType)return Results.BadRequest();bool permitted=false;if(type=="action"){var a=await db.Actions.FindAsync(id);permitted=a!=null&&Logic.Edit(u,a);}if(type=="gate"){var g=await db.Gate.FindAsync(id);permitted=g!=null&&Logic.EditOwner(u,g.OwnerId);}if(type=="measurement"){var m=await db.Measurements.FindAsync(id);var k=m==null?null:await db.Kpis.FindAsync(m.KpiId);permitted=k!=null&&Logic.EditOwner(u,k.OwnerId);}if(!permitted)return Results.Forbid();var form=await request.ReadFormAsync();var file=form.Files.GetFile("file");if(file==null||file.Length==0||file.Length>20*1024*1024)return Results.BadRequest(new{error="Selecciona um ficheiro até 20 MB."});var name=Path.GetFileName(file.FileName);var ext=Path.GetExtension(name).ToLowerInvariant();if(!new[]{".pdf",".png",".jpg",".jpeg",".docx",".xlsx",".csv",".txt"}.Contains(ext))return Results.BadRequest(new{error="Formato não permitido."});var e=new Evidence{Name=name,StoredName=Guid.NewGuid().ToString("N")+ext,Size=file.Length,UploadedBy=Logic.Person(u),MimeType="application/octet-stream",ActionId=type=="action"?id:null,GateId=type=="gate"?id:null,MeasurementId=type=="measurement"?id:null};await using(var stream=File.Create(Path.Combine(root,"evidence",e.StoredName)))await file.CopyToAsync(stream);db.Evidence.Add(e);if(type=="action"){var a=await db.Actions.FindAsync(id);a!.Version++;a.UpdatedAt=Logic.Now;db.Changes.Add(new(){ActionId=id,Actor=Logic.Person(u),Description=$"Evidência anexada: {name}"});}await db.SaveChangesAsync();return Results.Ok(new{e.Id,e.Name});}).DisableAntiforgery();
api.MapGet("/evidence/{id:guid}",async(Guid id,AppDb db)=>{var e=await db.Evidence.FindAsync(id);if(e==null)return Results.NotFound();var path=Path.Combine(root,"evidence",e.StoredName);return File.Exists(path)?Results.File(path,e.MimeType,e.Name):Results.NotFound();});
api.MapGet("/meetings",async(AppDb db)=>Results.Ok(await db.Meetings.OrderBy(x=>x.ScheduledAt).ToListAsync()));
api.MapPost("/meetings",async(MeetingInput i,AppDb db)=>{if(string.IsNullOrWhiteSpace(i.Title))return Results.BadRequest();var m=new Meeting();ApplyMeeting(m,i);db.Meetings.Add(m);await db.SaveChangesAsync();return Results.Ok(m);}).RequireAuthorization("Leader");
api.MapPut("/meetings/{id:guid}",async(Guid id,MeetingInput i,AppDb db)=>{var m=await db.Meetings.FindAsync(id);if(m==null)return Results.NotFound();ApplyMeeting(m,i);await db.SaveChangesAsync();return Results.Ok(m);}).RequireAuthorization("Leader");
api.MapGet("/decisions",async(AppDb db)=>Results.Ok(await db.Decisions.OrderByDescending(x=>x.RequestedAt).ToListAsync()));
api.MapPost("/decisions",async(DecisionInput i,ClaimsPrincipal u,AppDb db)=>{if(u.IsInRole("ce")&&!Logic.Leader(u))return Results.Forbid();if(string.IsNullOrWhiteSpace(i.Request)||!await db.People.AnyAsync(x=>x.Id==i.ToPersonId))return Results.BadRequest();var d=new Decision{Request=i.Request,ToPersonId=i.ToPersonId,MeetingId=i.MeetingId,RequestedBy=Logic.Person(u)};db.Decisions.Add(d);await db.SaveChangesAsync();return Results.Ok(d);});
api.MapPut("/decisions/{id:guid}",async(Guid id,TextInput i,ClaimsPrincipal u,AppDb db)=>{var d=await db.Decisions.FindAsync(id);if(d==null)return Results.NotFound();if(!Logic.Leader(u)&&d.ToPersonId!=Logic.Person(u)&&!(u.IsInRole("ce")&&d.ToPersonId=="ce"))return Results.Forbid();if(string.IsNullOrWhiteSpace(i.Text))return Results.BadRequest();if(d.DecidedAt!=null)return Results.Conflict(new{error="A decisão já foi fechada."});d.Outcome=i.Text;d.DecidedAt=Logic.Now;await db.SaveChangesAsync();return Results.Ok(d);});
api.MapGet("/kpis",async(AppDb db)=>{var ks=await db.Kpis.Include(x=>x.Measurements).ThenInclude(x=>x.Evidence).ToListAsync();string[] order=["automated","optimized","reduction","products","pilots","revenue","ontime"];ks=ks.OrderBy(k=>Array.IndexOf(order,k.Code)).ToList();var output=new List<object>();foreach(var k in ks)output.Add(new{k.Id,k.Code,k.Name,k.Unit,k.Target,k.TargetDate,k.InterimTarget,k.InterimDate,k.OwnerId,k.Calculated,k.Measurements,value=await Logic.KpiValue(db,k)});return Results.Ok(output);});
api.MapPost("/kpis/{id:guid}/measurements",async(Guid id,MeasurementInput i,ClaimsPrincipal u,AppDb db)=>{var k=await db.Kpis.FindAsync(id);if(k==null)return Results.NotFound();if(!Logic.EditOwner(u,k.OwnerId))return Results.Forbid();if(k.Calculated)return Results.BadRequest(new{error="Este KPI é calculado, não aceita valores manuais."});if(i.Value<0||k.Unit=="%"&&i.Value>100||i.MeasuredOn>Logic.Today||string.IsNullOrWhiteSpace(i.Source))return Results.BadRequest(new{error="Revê valor, data e fonte."});if(await db.Measurements.AnyAsync(x=>x.KpiId==id&&x.MeasuredOn==i.MeasuredOn))return Results.Conflict(new{error="Já existe uma medição nesta data."});var m=new Measurement{KpiId=id,Value=i.Value,MeasuredOn=i.MeasuredOn,Source=i.Source,Comment=i.Comment,RecordedBy=Logic.Person(u)};db.Measurements.Add(m);await db.SaveChangesAsync();return Results.Ok(m);});
api.MapPut("/kpis/{id:guid}/target",async(Guid id,TargetInput i,AppDb db)=>{var k=await db.Kpis.FindAsync(id);if(k==null)return Results.NotFound();if(k.Code!="revenue"||i.Target<0)return Results.BadRequest();k.Target=i.Target;await db.SaveChangesAsync();return Results.Ok();}).RequireAuthorization("Leader");
api.MapPost("/kpis/import",async(ImportInput i,ClaimsPrincipal u,AppDb db)=>{if(i.Rows.Count==0||i.Rows.Count>500)return Results.BadRequest();var errors=new List<string>();var pending=new List<Measurement>();var duplicate=new HashSet<string>();foreach(var row in i.Rows){var k=await db.Kpis.FindAsync(row.KpiId);if(k==null||k.Calculated||!Logic.EditOwner(u,k.OwnerId)||row.Value<0||k.Unit=="%"&&row.Value>100||row.MeasuredOn>Logic.Today||string.IsNullOrWhiteSpace(row.Source)||!duplicate.Add($"{row.KpiId}:{row.MeasuredOn}")||await db.Measurements.AnyAsync(x=>x.KpiId==row.KpiId&&x.MeasuredOn==row.MeasuredOn))errors.Add($"Linha {pending.Count+errors.Count+1}: KPI, valor, data, fonte, permissão ou duplicado inválido.");else pending.Add(new(){KpiId=row.KpiId,Value=row.Value,MeasuredOn=row.MeasuredOn,Source=row.Source,Comment=row.Comment,RecordedBy=Logic.Person(u)});}if(errors.Count>0)return Results.BadRequest(new{errors});if(!i.Commit)return Results.Ok(new{preview=pending,count=pending.Count});db.Measurements.AddRange(pending);await db.SaveChangesAsync();return Results.Ok(new{count=pending.Count});});
api.MapGet("/processes",async(AppDb db)=>Results.Ok(await db.Processes.OrderBy(x=>x.Name).ToListAsync()));
api.MapPost("/processes",async(ProcessInput i,ClaimsPrincipal u,AppDb db)=>{if(!Logic.Leader(u)&&!new[]{"ines","aniceto"}.Contains(Logic.Person(u)))return Results.Forbid();if(string.IsNullOrWhiteSpace(i.Name)||i.Optimized&&!i.Mapped||i.Automated&&!i.Internal||string.IsNullOrWhiteSpace(i.Evidence)||i.VerifiedOn>Logic.Today)return Results.BadRequest(new{error="Indica fonte e data de validação. Optimização exige mapeamento."});if(!await db.People.AnyAsync(x=>x.Id==i.OwnerId))return Results.BadRequest();if(await db.Processes.AnyAsync(x=>x.Name.ToLower()==i.Name.Trim().ToLower()))return Results.Conflict(new{error="Este processo já existe no inventário."});db.Processes.Add(new(){Name=i.Name.Trim(),OwnerId=i.OwnerId,Internal=i.Internal,Mapped=i.Mapped,Automated=i.Automated,Optimized=i.Optimized,Evidence=i.Evidence,VerifiedOn=i.VerifiedOn});await db.SaveChangesAsync();return Results.Ok();});
api.MapGet("/gate",async(AppDb db)=>Results.Ok(await db.Gate.Include(x=>x.Evidence).OrderBy(x=>x.Number).ToListAsync()));
api.MapPut("/gate/{id:guid}",async(Guid id,ConfirmInput i,ClaimsPrincipal u,AppDb db)=>{if(!Logic.Leader(u)&&!u.IsInRole("ce"))return Results.Forbid();var g=await db.Gate.Include(x=>x.Evidence).FirstOrDefaultAsync(x=>x.Id==id);if(g==null)return Results.NotFound();if(i.Confirmed&&!g.Evidence.Any())return Results.BadRequest(new{error="O critério exige evidência antes de ser confirmado."});g.Confirmed=i.Confirmed;g.ConfirmedBy=Logic.Person(u);g.ConfirmedAt=i.Confirmed?Logic.Now:null;await db.SaveChangesAsync();return Results.Ok(g);});
api.MapPost("/gate/launch",async(TextInput i,ClaimsPrincipal u,AppDb db)=>{if(!u.IsInRole("ce"))return Results.Forbid();var all=await db.Gate.ToListAsync();if(all.Count!=6||all.Any(x=>!x.Confirmed))return Results.BadRequest(new{error="Os seis critérios têm de estar confirmados."});if(string.IsNullOrWhiteSpace(i.Text))return Results.BadRequest();if(await db.Settings.AnyAsync(x=>x.Key=="gate.decision"))return Results.Conflict();db.Settings.Add(new(){Key="gate.decision",Value=JsonSerializer.Serialize(new{decision=i.Text,actor=Logic.Person(u),at=Logic.Now})});await db.SaveChangesAsync();return Results.Ok();});
api.MapGet("/gate/decision",async(AppDb db)=>Results.Ok(new{decision=await db.Settings.Where(x=>x.Key=="gate.decision").Select(x=>x.Value).FirstOrDefaultAsync()}));
api.MapGet("/notifications",async(ClaimsPrincipal u,AppDb db)=>{var list=await db.Notifications.Where(x=>x.PersonId==Logic.Person(u)).ToListAsync();return Results.Ok(list.OrderByDescending(x=>x.CreatedAt).Take(100));});
api.MapPut("/notifications/{id:guid}/read",async(Guid id,ClaimsPrincipal u,AppDb db)=>{var n=await db.Notifications.FindAsync(id);if(n==null||n.PersonId!=Logic.Person(u))return Results.NotFound();n.Read=true;await db.SaveChangesAsync();return Results.Ok();});
api.MapGet("/reports",async(AppDb db)=>Results.Ok(await db.Reports.OrderByDescending(x=>x.Month).ToListAsync()));
api.MapGet("/reports/preview",async(AppDb db)=>Results.Ok(await Logic.Snapshot(db)));
api.MapPost("/reports",async(ReportInput i,AppDb db)=>{if(!System.Text.RegularExpressions.Regex.IsMatch(i.Month,@"^\d{4}-(0[1-9]|1[0-2])$")||await db.Reports.AnyAsync(x=>x.Month==i.Month))return Results.BadRequest(new{error="Mês inválido ou reporte já arquivado."});var snapshot=await Logic.Snapshot(db);var report=new MonthlyReport{Month=i.Month,Snapshot=JsonSerializer.Serialize(snapshot,new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase}),ExecutiveSummary=i.ExecutiveSummary};db.Reports.Add(report);await db.SaveChangesAsync();return Results.Ok(report);}).RequireAuthorization("Leader");
var leader=api.MapGroup("/cto").RequireAuthorization("Leader");
leader.MapGet("/notes",async(AppDb db)=>Results.Ok(await db.PrivateNotes.OrderByDescending(x=>x.At).ToListAsync()));
leader.MapPost("/notes",async(TextInput i,AppDb db)=>{if(string.IsNullOrWhiteSpace(i.Text)||i.Text.Length>10000)return Results.BadRequest();db.PrivateNotes.Add(new(){Text=i.Text});await db.SaveChangesAsync();return Results.Ok();});
leader.MapGet("/advisor/history",async(AppDb db)=>Results.Ok(await db.AdvisorTurns.OrderByDescending(x=>x.At).Take(30).ToListAsync()));
leader.MapPost("/advisor",async(TextInput i,Advisor advisor,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(i.Text)||i.Text.Length>3000)return Results.BadRequest();try{return Results.Ok(new{answer=await advisor.Answer(i.Text,ct)});}catch(InvalidOperationException ex){return Results.Json(new{error=ex.Message},statusCode:503);}catch(OperationCanceledException){return Results.Json(new{error="A análise excedeu o tempo disponível. Tenta novamente."},statusCode:504);}}).RequireRateLimiting("advisor");
leader.MapGet("/settings",async(AppDb db)=>{var all=await db.Settings.ToListAsync();return Results.Ok(new{values=all.Where(x=>!ConfigurationStore.Secret(x.Key)&&x.Key!="gate.decision").ToDictionary(x=>x.Key,x=>x.Value),openAiKeyConfigured=all.Any(x=>x.Key=="openai.key"&&x.Value.Length>0),smtpPasswordConfigured=all.Any(x=>x.Key=="smtp.password"&&x.Value.Length>0),rules=await db.AlertRules.ToListAsync()});});
leader.MapPut("/settings",async(SettingsInput i,ConfigurationStore store,AppDb db)=>{string[] allowed=["openai.key","openai.model","smtp.host","smtp.port","smtp.tls","smtp.user","smtp.password","smtp.from","email.mode","email.hour","app.publicUrl"];foreach(var p in i.Values){if(!allowed.Contains(p.Key)||p.Value.Length>2000)return Results.BadRequest();if(ConfigurationStore.Secret(p.Key)&&p.Value.Length==0)continue;if(p.Key=="smtp.port"&&(!int.TryParse(p.Value,out var port)||port<1||port>65535))return Results.BadRequest();if(p.Key=="email.hour"&&(!int.TryParse(p.Value,out var hour)||hour<0||hour>23))return Results.BadRequest();if(p.Key=="email.mode"&&!new[]{"instant","daily","weekly"}.Contains(p.Value))return Results.BadRequest();await store.Save(p.Key,p.Value);}await db.SaveChangesAsync();return Results.Ok();});
leader.MapPost("/settings/smtp-test",async(ClaimsPrincipal actor,UserManager<User> users,SmtpMailer mailer,CancellationToken ct)=>{
 var member=await users.GetUserAsync(actor);if(member?.Email==null)return Results.BadRequest(new{error="A tua conta não tem email configurado."});
 try{await mailer.Send(member.Email,"UCALL Transformação · teste de e-mail","Olá, "+member.DisplayName+".\n\nEste é o teu e-mail de teste da plataforma UCALL Transformação. A configuração está pronta para enviar os alertas.\n\nTeste pedido por "+member.DisplayName+" em "+Logic.Luanda(Logic.Now).ToString("dd/MM/yyyy HH:mm")+" (Angola).",ct);return Results.Ok(new{message="O servidor SMTP aceitou o email de teste. Confirma a recepção na tua caixa de entrada ou no spam."});}
 catch(System.Net.Mail.SmtpException ex){var error=ex.StatusCode==System.Net.Mail.SmtpStatusCode.ClientNotPermitted?"O servidor recusou a autenticação ou o envio. Revê utilizador, password e permissões do remetente.":"O servidor SMTP recusou o envio. Revê servidor, porta, TLS, credenciais e permissões do remetente.";return Results.Json(new{error},statusCode:502);}
 catch(OperationCanceledException){return Results.Json(new{error="O servidor SMTP não respondeu em 20 segundos. Revê endereço, porta e acesso de rede."},statusCode:504);}
 catch(FormatException){return Results.BadRequest(new{error="O endereço do remetente não é válido."});}
 catch(InvalidOperationException ex){return Results.BadRequest(new{error=ex.Message});}
 }).RequireRateLimiting("login");
leader.MapDelete("/settings/openai-key",async(ConfigurationStore store,AppDb db)=>{await store.Save("openai.key","");await db.SaveChangesAsync();return Results.Ok();});
leader.MapPut("/alerts/{id:guid}",async(Guid id,AlertRuleInput i,AppDb db)=>{var r=await db.AlertRules.FindAsync(id);if(r==null)return Results.NotFound();if(i.RepeatEveryDays<1||i.EscalateAfterDays<1||i.SendHour<0||i.SendHour>23||i.DaysBefore.Split(',',StringSplitOptions.RemoveEmptyEntries).Any(x=>!int.TryParse(x,out var n)||n<0||n>365)||i.Recipients.Split(',').Any(x=>!new[]{"owner","participants","leader"}.Contains(x)))return Results.BadRequest();r.Enabled=i.Enabled;r.Email=i.Email;r.DaysBefore=i.DaysBefore;r.RepeatEveryDays=i.RepeatEveryDays;r.EscalateAfterDays=i.EscalateAfterDays;r.Recipients=i.Recipients;r.SendHour=i.SendHour;await db.SaveChangesAsync();return Results.Ok();});
leader.MapGet("/users",async(AppDb db,UserManager<User> manager)=>{var members=await db.Users.ToListAsync();var list=new List<object>();foreach(var member in members)list.Add(new{member.Id,member.Email,member.DisplayName,member.PersonId,active=member.LockoutEnd==null||member.LockoutEnd<=Logic.Now,disabled=member.LockoutEnd!=null&&member.LockoutEnd.Value.Year>=9990,roles=await manager.GetRolesAsync(member)});return Results.Ok(list);});
leader.MapPost("/users",async(UserInput input,AppDb db,UserManager<User> manager)=>{if(!new[]{"officer","guest","ce"}.Contains(input.Role))return Results.BadRequest(new{error="Perfil inválido."});await using var transaction=await db.Database.BeginTransactionAsync();Person? person;if(input.PersonId=="new"){if(string.IsNullOrWhiteSpace(input.DisplayName)||input.DisplayName.Length>120)return Results.BadRequest(new{error="Indica o nome da pessoa."});person=new Person{Id="person-"+Guid.NewGuid().ToString("N"),Name=input.DisplayName.Trim(),Area=input.Area??""};db.People.Add(person);}else{if(input.PersonId is "paulo" or "seniores" or "ce")return Results.BadRequest();person=await db.People.FindAsync(input.PersonId);if(person==null)return Results.BadRequest(new{error="Pessoa inválida."});if(await db.Users.AnyAsync(x=>x.PersonId==person.Id))return Results.Conflict(new{error="Esta pessoa já tem conta."});}var member=new User{UserName=input.Email.Trim(),Email=input.Email.Trim(),DisplayName=person.Name,PersonId=person.Id};var result=await manager.CreateAsync(member,input.Password);if(!result.Succeeded)return Results.BadRequest(new{error=string.Join(" ",result.Errors.Select(x=>x.Description))});result=await manager.AddToRoleAsync(member,input.Role);if(!result.Succeeded)return Results.BadRequest();await manager.AddClaimAsync(member,new Claim("person_id",person.Id));await transaction.CommitAsync();return Results.Ok(new{member.Id,member.PersonId});});
leader.MapPut("/users/{id}",async(string id,UserEditInput input,AppDb db,UserManager<User> manager,SignInManager<User> signIn,ClaimsPrincipal actor)=>{var member=await manager.FindByIdAsync(id);if(member==null)return Results.NotFound();if(string.IsNullOrWhiteSpace(input.DisplayName)||input.DisplayName.Length>120||string.IsNullOrWhiteSpace(input.Email))return Results.BadRequest(new{error="Revê nome e e-mail."});if(member.PersonId=="paulo"&&(input.Role!="leader"||!input.Active))return Results.BadRequest(new{error="A conta de Paulo mantém-se activa e com perfil de líder."});if(member.PersonId!="paulo"&&!new[]{"officer","guest","ce"}.Contains(input.Role))return Results.BadRequest(new{error="Perfil inválido."});var duplicate=await manager.FindByEmailAsync(input.Email.Trim());if(duplicate!=null&&duplicate.Id!=id)return Results.Conflict(new{error="Este e-mail já está associado a outra conta."});await using var transaction=await db.Database.BeginTransactionAsync();member.DisplayName=input.DisplayName.Trim();member.Email=input.Email.Trim();member.UserName=input.Email.Trim();member.LockoutEnabled=true;member.LockoutEnd=input.Active?null:DateTimeOffset.MaxValue;member.AccessFailedCount=0;var result=await manager.UpdateAsync(member);if(!result.Succeeded)return Results.BadRequest(new{error=string.Join(" ",result.Errors.Select(x=>x.Description))});var currentRoles=await manager.GetRolesAsync(member);await manager.RemoveFromRolesAsync(member,currentRoles);await manager.AddToRoleAsync(member,input.Role);await manager.UpdateSecurityStampAsync(member);var person=await db.People.FindAsync(member.PersonId);if(person!=null)person.Name=member.DisplayName;await db.SaveChangesAsync();await transaction.CommitAsync();if(member.Id==actor.FindFirstValue(ClaimTypes.NameIdentifier))await signIn.RefreshSignInAsync(member);return Results.Ok();});
leader.MapPost("/users/{id}/password",async(string id,PasswordInput input,UserManager<User> manager,SignInManager<User> signIn,ClaimsPrincipal actor)=>{var member=await manager.FindByIdAsync(id);if(member==null)return Results.NotFound();IdentityResult result;if(member.PersonId=="paulo"){if(member.Id!=actor.FindFirstValue(ClaimTypes.NameIdentifier)||string.IsNullOrEmpty(input.CurrentPassword))return Results.BadRequest(new{error="Indica a tua password actual."});result=await manager.ChangePasswordAsync(member,input.CurrentPassword,input.Password);if(result.Succeeded)await signIn.RefreshSignInAsync(member);}else{var token=await manager.GeneratePasswordResetTokenAsync(member);result=await manager.ResetPasswordAsync(member,token,input.Password);}return result.Succeeded?Results.Ok():Results.BadRequest(new{error=string.Join(" ",result.Errors.Select(x=>x.Code=="PasswordMismatch"?"A password actual não está correcta.":x.Description))});}).RequireRateLimiting("login");
app.MapFallbackToFile("index.html");
app.Run();

static async Task<string?> ValidateAction(ActionInput i,AppDb db,Guid? id=null){if(string.IsNullOrWhiteSpace(i.Title)||i.Title.Length>300||string.IsNullOrWhiteSpace(i.Deliverable)||!Logic.Statuses.Contains(i.Status)||i.Progress<0||i.Progress>100||i.Priority<1||i.Priority>6||!new[]{"Arranque","Diagnóstico","Desenhar a oferta","Pilotar","Lançar"}.Contains(i.Phase))return "Revê título, entregável, fase, prioridade, estado e avanço.";if(!await db.People.AnyAsync(x=>x.Id==i.OwnerId))return "Responsável inválido.";var people=await db.People.Select(x=>x.Id).ToListAsync();if(i.Participants.Split(',',StringSplitOptions.RemoveEmptyEntries).Any(x=>!people.Contains(x)))return "Participantes inválidos.";if(i.MeetingId!=null&&!await db.Meetings.AnyAsync(x=>x.Id==i.MeetingId))return "Reunião inválida.";if(i.KpiId!=null&&!await db.Kpis.AnyAsync(x=>x.Id==i.KpiId))return "KPI inválido.";if(i.DependsOnId!=null){var seen=new HashSet<Guid>();if(id!=null)seen.Add(id.Value);var cursor=i.DependsOnId;while(cursor!=null){if(!seen.Add(cursor.Value))return "A dependência criaria um ciclo.";var parent=await db.Actions.FindAsync(cursor.Value);if(parent==null)return "Dependência inválida.";cursor=parent.DependsOnId;}}return null;}
static void ApplyAction(WorkAction a,ActionInput i){a.Title=i.Title.Trim();a.Description=i.Description;a.Phase=i.Phase;a.Priority=i.Priority;a.OwnerId=i.OwnerId;a.Participants=i.Participants;a.DueDate=i.DueDate;a.Deliverable=i.Deliverable;a.Status=i.Status;a.Progress=i.Progress;a.MeetingId=i.MeetingId;a.DependsOnId=i.DependsOnId;a.KpiId=i.KpiId;}
static void ApplyMeeting(Meeting m,MeetingInput i){m.Title=i.Title.Trim();m.ScheduledAt=i.ScheduledAt.ToUniversalTime();m.Participants=i.Participants;m.Agenda=i.Agenda;m.Minutes=i.Minutes;m.MandateAccepted=i.MandateAccepted;}
record SetupInput(string Token,string Email,string Password);
record LoginInput(string Email,string Password);
record TextInput(string Text);
record ActionInput(string Title,string Description,string Phase,int Priority,string OwnerId,string Participants,DateOnly DueDate,string Deliverable,string Status,int Progress,int Version,string? DeadlineReason,Guid? MeetingId,Guid? DependsOnId,Guid? KpiId);
record SubtaskInput(string Title,bool Done);
record MeetingInput(string Title,DateTimeOffset ScheduledAt,string Participants,string Agenda,string Minutes,bool MandateAccepted);
record DecisionInput(string Request,string ToPersonId,Guid? MeetingId);
record MeasurementInput(decimal Value,DateOnly MeasuredOn,string Source,string Comment);
record TargetInput(decimal Target);
record ImportRow(Guid KpiId,decimal Value,DateOnly MeasuredOn,string Source,string Comment);
record ImportInput(List<ImportRow> Rows,bool Commit);
record ProcessInput(string Name,string OwnerId,bool Internal,bool Mapped,bool Automated,bool Optimized,string Evidence,DateOnly VerifiedOn);
record ConfirmInput(bool Confirmed);
record ReportInput(string Month,string ExecutiveSummary);
record SettingsInput(Dictionary<string,string> Values);
record AlertRuleInput(bool Enabled,bool Email,string DaysBefore,int RepeatEveryDays,int EscalateAfterDays,string Recipients,int SendHour);
record UserInput(string PersonId,string Email,string Password,string Role,string? DisplayName=null,string? Area=null);
record UserEditInput(string DisplayName,string Email,string Role,bool Active);
record PasswordInput(string Password,string? CurrentPassword=null);

